import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"12、【否】 坤下乾上","description":"橫渠易說 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"橫渠易說 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"classics/hengqu/014.md","filePath":"classics/hengqu/014.md"}'),l={name:"classics/hengqu/014.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><h3 id="彖曰-否之匪人-不利君子貞-大往小來-則是天地不交而萬物不通也-上下不交而天下無邦也。內陰而外陽-內柔而外剛-內小人而外君子-小人道長-君子道消也。" tabindex="-1">彖曰：“否之匪人，不利君子貞，大往小來”，則是天地不交而萬物不通也，上下不交而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子，小人道長，君子道消也。 <a class="header-anchor" href="#彖曰-否之匪人-不利君子貞-大往小來-則是天地不交而萬物不通也-上下不交而天下無邦也。內陰而外陽-內柔而外剛-內小人而外君子-小人道長-君子道消也。" aria-label="Permalink to “彖曰：“否之匪人，不利君子貞，大往小來”，則是天地不交而萬物不通也，上下不交而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子，小人道長，君子道消也。”">​</a></h3><h3 id="象曰-天地不交-否-君子以險德闢難-不可榮以祿。" tabindex="-1">象曰：天地不交，否，君子以險德闢難，不可榮以祿。 <a class="header-anchor" href="#象曰-天地不交-否-君子以險德闢難-不可榮以祿。" aria-label="Permalink to “象曰：天地不交，否，君子以險德闢難，不可榮以祿。”">​</a></h3><p>蓋言上下不交便天下無邦，有邦而與無邦同，以不成國體也。在天下，他國皆無道，只一邦治，亦不可言天下無道，須是都不治然後是天下無道也。於否之時，則天下無邦也。古之人，一邦不治，別之一邦，直至天下皆無邦可之，則止有隱耳。無道而隱，則惟是有朋友之樂而已。子欲居九夷，未敢必天下之無邦，或夷狄有道，於今海上之國盡有仁厚之治者。</p><h3 id="初六-拔茅茹-以其匯-貞吉亨。-象曰-拔茅貞吉-志在君也。" tabindex="-1">初六，拔茅茹，以其匯，貞吉亨。 象曰：“拔茅貞吉”，志在君也。 <a class="header-anchor" href="#初六-拔茅茹-以其匯-貞吉亨。-象曰-拔茅貞吉-志在君也。" aria-label="Permalink to “初六，拔茅茹，以其匯，貞吉亨。 象曰：“拔茅貞吉”，志在君也。”">​</a></h3><p>柔順處下，居否以靜者也。能以類正，吉而必亨，不事苟合，志在得主者歟!</p><h3 id="六二-包承-小人吉-大人否-亨。-象曰-大人否亨了-不亂群也。" tabindex="-1">六二，包承，小人吉，大人否，亨。 象曰：“大人否亨了”，不亂群也。 <a class="header-anchor" href="#六二-包承-小人吉-大人否-亨。-象曰-大人否亨了-不亂群也。" aria-label="Permalink to “六二，包承，小人吉，大人否，亨。 象曰：“大人否亨了”，不亂群也。”">​</a></h3><p>處二陰之間，上順下容，眾不可異，故其道否乃亨。</p><h3 id="六三-包羞。-象曰-包羞-位不當也。" tabindex="-1">六三，包羞。 象曰：“包羞”，位不當也。 <a class="header-anchor" href="#六三-包羞。-象曰-包羞-位不當也。" aria-label="Permalink to “六三，包羞。 象曰：“包羞”，位不當也。”">​</a></h3><p>處否而進，履非其位，非知恥者也。</p><h3 id="九四-有命無咎-疇離祉。-象曰-有命無咎-志行也。" tabindex="-1">九四，有命無咎，疇離祉。 象曰：“有命無咎”，志行也。 <a class="header-anchor" href="#九四-有命無咎-疇離祉。-象曰-有命無咎-志行也。" aria-label="Permalink to “九四，有命無咎，疇離祉。 象曰：“有命無咎”，志行也。”">​</a></h3><p>居否之世，以陽處陰，有應於下，故雖有所命無咎也。</p><h3 id="九五-休否-大人吉。其亡其亡-繫於苞桑。-象曰-大人之吉-位正當也。" tabindex="-1">九五，休否，大人吉。其亡其亡，繫於苞桑。 象曰：大人之吉，位正當也。 <a class="header-anchor" href="#九五-休否-大人吉。其亡其亡-繫於苞桑。-象曰-大人之吉-位正當也。" aria-label="Permalink to “九五，休否，大人吉。其亡其亡，繫於苞桑。 象曰：大人之吉，位正當也。”">​</a></h3><p>以亡為懼，故能休其否。包桑，從下叢生之桑，叢生則其根牢。書雲“厥草惟包”，如竹叢蘆葦之類。河朔之桑，多從根斬條取葉，其生叢然。</p><h3 id="上九-傾否-先否後喜。-象曰-否終則傾-何可長也" tabindex="-1">上九，傾否，先否後喜。 象曰：否終則傾，何可長也! <a class="header-anchor" href="#上九-傾否-先否後喜。-象曰-否終則傾-何可長也" aria-label="Permalink to “上九，傾否，先否後喜。 象曰：否終則傾，何可長也!”">​</a></h3>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
